    if (k === "=O" || k === "COO") { atoms.push(A(id, [c.x, c.y + 30 * d], "O", "O")); bonds.push([c.id, id, 2]); }
    if (k === "COO") { atoms.push(A(id + "b", nx, "O", "O", { q: "−" })); bonds.push([c.id, id + "b"]); }
