    if (k === "COOL") { atoms.push(A(id, [c.x, c.y + 30 * d], "O", "O"), A(id + "b", [c.x - dx, (i - 1) % 2 ? 0 : 15], "O", "O", { q: "−", qd: [-8, -8] })); bonds.push([c.id, id, 2], [c.id, id + "b"]); }
    if (k === "NH3") { atoms.push(A(id, [c.x, c.y + 30 * d], "NH3", "N", { q: "+", qd: [14, -8] })); bonds.push([c.id, id]); }
