  const u = unit(P[1]), c = [P[1][0] + u[0] * 30, P[1][1] + u[1] * 30], v = rot(u, 40);
  atoms.push(C("cm", c), A("nm", [c[0] + v[0] * 30, c[1] + v[1] * 30], "NH3", "N", { q: "+", qd: [14, -8] }));
