  atoms.push(...MOLS.atp.atoms.filter((a) => keep.has(a.id)).map((a) => ({ ...a })));
  bonds.push(...MOLS.atp.bonds.filter((b) => keep.has(b[0]) && keep.has(b[1])).map((b) => (b[0] === "C4" && b[1] === "C5" ? ["C4", "C5", 2, [46.6, 0]] : [...b])), ["N9", "C1p"]);
