  cy.atoms.push(A("s", [104, 15], "S", "S"), C("d1", [130, 0]), C("d2", [156, 15]), C("d3", [182, 0]), A("dn", [156, 45], "NH3", "N", { q: "+", qd: [14, -8] }), A("do1", [182, -30], "O", "O"), A("do2", [208, 15], "O", "O", { q: "−" }));
  cy.bonds.push(["c3", "s"], ["s", "d1"], ["d1", "d2"], ["d2", "d3"], ["d2", "dn"], ["d3", "do1", 2], ["d3", "do2"]);
