  chairAtoms().filter((a) => a.id !== "O1").forEach((a) => { m.atoms.push(a); m.pos[a.id] = [a.x, a.y]; });
  chairBonds.filter((b) => b[1] !== "O1").forEach((b) => m.bonds.push(b));
  m.at("O6", ...pt(-1.65, 1.02), "HO", "O", { align: "end" });
