  m.ring("B", "b0", -19.4, 6, [1, 3, 5]);
  m.to(m.id("B", 3), "Cl", m.out("B", 3), "Cl", "Cl");
  m.to(m.id("B", 4), "bz", m.out("B", 4), null).to("bz", "c0", m.out("B", 4) - 60, null);
  m.ring("D", "c0", m.out("B", 4) - 60, 6, [1, 3, 5]);
