  m.walk("p1", 330, 60, [["p2"], ["p3", null, null, 2], ["p4"], ["p5"], ["p6"], ["p7"], ["p8"], ["p9"], ["p10"], ["p11"], ["p12"], ["p13"], ["p14"], ["p15"], ["p16"]]);
  ["p3", "p7", "p11", "p15"].forEach((k) => m.to(k, "q" + k, 90, null));
