  const gIds = editing && groupMove && gHot ? EDIT_GROUPS.members.get(gHot) : null;
  const gOutline = gIds && gIds.length > 1 ? `${gIds.map((id) => `.omino-canvas .react-flow__node[data-id="${String(id).replace(/["\\]/g, "\\$&")}"]`).join(",")}{outline:2px dashed var(--sky);outline-offset:6px;border-radius:14px}` : "";
  const [hoverEdge, setHoverEdge] = useState(null); // line under the pointer
  const hopped = useRef(false); // set when Back / Follow swaps the card, so the card-open recentring does not fire twice
  const [track, setTrack] = useState(null); // follower: { at: object id, inn: incoming line id, out: outgoing line id }
  const [query, setQuery] = useState("");
  const [hideG, setHideG] = useState(false); // G: enzymes (edge labels)
  const [hideS, setHideS] = useState(true); // S: substrates / co-substrates (hidden by default; the S button or the Substrates setting shows them)
  const [focus, setFocus] = useState(null); // highlighted pathway
  const [scrollPans, setScrollPans] = useState(false); // scroll wheel / trackpad: zoom (default) or pan
  const { fitView, zoomIn, zoomOut, getViewport, setViewport, getNode, setCenter, getZoom, screenToFlowPosition } = useReactFlow();
  const [zoomLock, setZoomLock] = useState(false); // keeps the camera still while the location / organ / pathway chips are switched
  const lockTimer = useRef(null), lockFired = useRef(false);
  const chipFit = (opts) => { if (!zoomLock) fitView(opts); };
  const [ptOpen, setPtOpen] = useState(false); // periodic table panel
  const [rdx, setRdx] = useState(null); // Follow e⁻ and H: index of the step being shown, or null when the panel is closed
  const [rdxPlay, setRdxPlay] = useState(false);
  const [fpOpen, setFpOpen] = useState(false); // Follow panel: Pathways (rdx == null) or e⁻ and H (rdx = step)
  const rdxLit = useMemo(() => (rdx == null ? null : RDX_LIT(rdx)), [rdx]); // canvas objects on the route so far
  const [stOpen, setStOpen] = useState(false); // settings panel
  const [navOn, setNavOn] = useState(false); // navigation add-ons (tool column, minimap, legend, filter chips): the canvas opens clear and the round compass button in the top bar engages them
  const [showMini, setShowMini] = useState(true); // overview (minimap)
  const [showPaths, setShowPaths] = useState(true); // pathway chip bar
  const [showRx, setShowRx] = useState(true); // pharmacology layer (drugs, targets, effect lines)
  const [showKey, setShowKey] = useState(true); // legend for the pharmacology lines, toggled separately from the layer
  const [showChips, setShowChips] = useState(true); // the filter chip rows along the bottom (collapsible from the left column)
  const [showLoc, setShowLoc] = useState(true); // cellular-location tags and filter chips
  const [showOrgans, setShowOrgans] = useState(true); // organ hubs (part of the pharmacology layer)
  const [locFocus, setLocFocus] = useState(null);
  const [organFocus, setOrganFocus] = useState(null);
  const chipWheel = (e) => { if (!e.deltaX) e.currentTarget.scrollLeft += e.deltaY; };
  const toggleLoc = () => {
    if (showLoc) { setLocFocus(null); setStack((s) => s.filter((x) => x.t !== "loc")); }
    setShowLoc((v) => !v);
  };
  const toggleOrgans = () => {
    if (showOrgans) { setOrganFocus(null); setStack((s) => s.filter((x) => x.t !== "organ")); }
    else setShowRx(true);
    setShowOrgans((v) => !v);
  };
  const toggleRx = () => {
    if (showRx) { setOrganFocus(null); if (focus === "pharm") setFocus(null); setStack((s) => s.filter((x) => x.t !== "drug" && x.t !== "target" && x.t !== "organ" && !(x.t === "path" && x.id === "pharm"))); }
    setShowRx((v) => !v);
  };
